changeSet.sql:
create or replace function trg_memories_touch_last_refreshed()
returns trigger
language plpgsql
as $$
begin
  new.last_refreshed := now();
  return new;
end;
$$;

drop trigger if exists memories_touch_last_refreshed on memories;
create trigger memories_touch_last_refreshed
before update on memories
for each row
execute function trg_memories_touch_last_refreshed();

do $$
begin
  if exists (select 1 from pg_extension where extname = 'vector') then
    begin
      alter table memories add column if not exists embedding vector(1536);
      create index if not exists mem_vec_idx on memories using ivfflat (embedding vector_cosine) with (lists = 200);
    exception when others then
      raise notice 'Vector column/index already configured: %', sqlerrm;
    end;
  end if;
end;
$$;

alter table memories enable row level security;
create policy if not exists memories_isolation on memories
  using (user_id = coalesce(nullif(current_setting('app.user_id', true), '')::bigint, -1));

alter table learning_plan enable row level security;
create policy if not exists learning_plan_isolation on learning_plan
  using (user_id = coalesce(nullif(current_setting('app.user_id', true), '')::bigint, -1));

create table if not exists xp_events_2025_10
  partition of xp_events
  for values from ('2025-10-01') to ('2025-11-01');

create index if not exists xp_events_2025_10_user_idx
  on xp_events_2025_10 (user_id, happened_at desc);

do $$
declare
    start_month date := date_trunc('month', current_date)::date;
    start_date date;
    end_date date;
    partition_name text;
    i int;
begin
    for i in 0..3 loop
        start_date := (start_month + (i || ' months')::interval)::date;
        end_date := (start_month + ((i + 1) || ' months')::interval)::date;
        partition_name := 'xp_events_' || to_char(start_date, 'YYYY_MM');

        execute format(
            'create table if not exists %I partition of xp_events for values from (%L) to (%L)',
            partition_name,
            start_date,
            end_date
        );

        execute format(
            'create index if not exists %I on %I (user_id, happened_at desc)',
            partition_name || '_user_idx',
            partition_name
        );
    end loop;
end
$$;

alter table xp_events enable row level security;
create policy if not exists xp_events_isolation on xp_events
  using (user_id = coalesce(nullif(current_setting('app.user_id', true), '')::bigint, -1));

changeSet.rollback:
DROP TABLE IF EXISTS xp_events CASCADE;
DROP TABLE IF EXISTS learning_plan CASCADE;
DROP TABLE IF EXISTS memories CASCADE;
DROP FUNCTION IF EXISTS trg_memories_touch_last_refreshed();
